    const r = spawnSync(process.execPath, [join(CANON, entry)], { encoding: 'utf8', env });
    assert.equal(r.status, 0, `${entry}: ${r.stdout}${r.stderr}`);
    assert.ok(r.stdout.includes(suspendedNotice()), `${entry}: a held run must say it is held`);
